[
  {
    "text": "Retrieval failures that appear only when cross-document dependencies are broken persist in a test corpus where both item-level and document-level metadata are filled to a verified completeness standard.",
    "topic": "cross-document gap independence"
  },
  {
    "text": "When document-level metadata is intentionally degraded while cross-document links remain intact, the resulting retrieval errors are disjoint from those produced by breaking cross-document links alone.",
    "topic": "failure mode separation"
  },
  {
    "text": "The set of queries that fail due to missing inter-document links is experimentally distinguishable from the set that fails due to incomplete document-level metadata by checking whether restoring only document-level metadata resolves the failures.",
    "topic": "causal attribution"
  },
  {
    "text": "An experiment that systematically varies cross-document link integrity and document-level metadata completeness shows a significant interaction effect that fuses the two failure modes into one.",
    "topic": "failure mode interaction"
  }
]
